<template><main class="rentals-page"><div class="container py-5"><div class="page-head"><div><p>Mi cuenta</p><h1>Mis alquileres</h1><span>Consulta estados, pagos y próximos pasos.</span></div><RouterLink to="/alquiler" class="btn btn-primary">Explorar equipos</RouterLink></div><div v-if="store.loading" class="row g-3"><div v-for="n in 3" :key="n" class="col-12"><div class="skeleton"></div></div></div><div v-else-if="store.error" class="alert alert-warning">{{ store.error }}</div><div v-else-if="!store.items.length" class="empty"><i class="bi bi-calendar2-check"></i><h2>Aún no tienes alquileres</h2><p>Encuentra el equipo ideal y reserva en pocos minutos.</p><RouterLink to="/alquiler" class="btn btn-primary">Ver catálogo</RouterLink></div><div v-else class="rental-list"><article v-for="item in store.items" :key="item.uuid"><RentalStatusCard :title="item.equipment_name||item.equipment_variant_name||'Equipo en alquiler'" :image="item.equipment_image" :status-label="statusLabel(item.status)" :dates="dates(item)" :payment-label="item.payment_status_display||item.payment_status||'Pago pendiente'" :to="{name:'rental-confirmation',params:{uuid:item.uuid}}"/><details><summary>Ver seguimiento</summary><RentalTimeline :status="item.status"/><button class="btn btn-outline-primary btn-sm w-100 mt-3" @click="askForHelp(item)"><i class="bi bi-headset me-1"></i>¿Necesitas ayuda con este alquiler?</button></details></article></div></div></main></template>
<script setup>import{onMounted}from'vue';import{useRentalsStore}from '@/store/renting/rentalsStore';import RentalStatusCard from '@/components/customer/renting/RentalStatusCard.vue';import RentalTimeline from '@/components/customer/renting/RentalTimeline.vue';import{useEnums}from '@/composables/useEnums';import{useSupportContextStore}from '@/store/supportContext';const store=useRentalsStore();const enums=useEnums();const supportContextStore=useSupportContextStore();const statusLabel=s=>enums.label('rental-statuses',s,s||'En revision');const dates=i=>i.start_date&&i.end_date?`${i.start_date} — ${i.end_date}`:'Programación por confirmar';const askForHelp=item=>supportContextStore.requestHelp('RENTAL',item.uuid);onMounted(()=>{enums.ensure('rental-statuses');store.fetch();});</script>
<style scoped>.rentals-page{min-height:100vh;background:#f8f8fb}.page-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:2rem}.page-head p{color:#7c3aed;text-transform:uppercase;font-size:.72rem;font-weight:800;letter-spacing:.12em;margin:0}.page-head h1{font-weight:850;margin:.3rem 0}.page-head span{color:#64748b}.rental-list{display:grid;gap:1rem}.rental-list article{display:grid;gap:.6rem}details{background:#fff;border:1px solid #e8e7ee;border-radius:16px;padding:.8rem 1rem}summary{cursor:pointer;color:#6d28d9;font-weight:700}details :deep(.rental-timeline){margin-top:1rem!important}.empty{text-align:center;background:#fff;border-radius:24px;padding:4rem 1rem}.empty i{font-size:3rem;color:#c4b5fd}.skeleton{height:125px;border-radius:20px;background:linear-gradient(90deg,#eee,#f8f8f8,#eee);background-size:200%;animation:p 1.2s infinite}@keyframes p{to{background-position:-200%}}@media(max-width:600px){.page-head{align-items:start;gap:1rem;flex-direction:column}}</style>
